import {validValue,defaultsFor} from './blueprint-model.js';
import {actorClassNames} from './runtime-actors.js';
export const sequenceValueTypes=['bool','int','float','string','vec2','vec3','color','object','transform','hit'];
const safe=id=>typeof id==='string'&&id.length>0&&id.length<=100&&!['__proto__','constructor','prototype'].includes(id);
export const sequenceValueDiscrete=track=>track.array||!['float','vec2','vec3','color'].includes(track.valueType);
export function validSequenceValue(track,value){return ['variable','nativeProperty'].includes(track.type)&&sequenceValueTypes.includes(track.valueType)&&typeof track.array==='boolean'&&(track.type==='variable'?safe(track.variable):safe(track.className)&&safe(track.property)&&/^[A-Za-z_]\w*$/.test(track.className)&&/^[A-Za-z_]\w*$/.test(track.property))&&(track.array?Array.isArray(value)&&value.length<=128&&value.every(v=>validValue(track.valueType,v)):validValue(track.valueType,value))&&JSON.stringify(value).length<=65536;}
function descriptor(object,track,bindings){const matches=bindings.filter(b=>b.self===object?.id);if(track.type==='variable'){for(const binding of matches){const definition=binding.root.variables.find(v=>v.id===track.variable);if(definition&&definition.type===track.valueType&&(definition.container==='array')===track.array)return {object,binding,definition,value:binding.variables.has(definition.id)?binding.variables.get(definition.id):definition.value};}}else if(object?.nativeClass===track.className){for(const binding of matches){const definition=binding.root.native?.classes.find(c=>c.name===track.className)?.properties.find(p=>p.name===track.property);if(definition&&!definition.readOnly&&definition.type===track.valueType&&definition.array===track.array)return {object,definition,value:Object.hasOwn(object.nativeProperties||{},track.property)?object.nativeProperties[track.property]:definition.value??(definition.array?[]:defaultsFor(definition.type))};}}throw Error('시퀀스 변수의 대상·선언·자료형이 바뀌었어요: '+(track.variable||track.property));}
export function recordableRuntimeValues(object,bindings){const rows=[],seen=new Set();for(const binding of bindings.filter(b=>b.self===object.id)){for(const definition of binding.root.variables){if(seen.has('v:'+definition.id))continue;seen.add('v:'+definition.id);const track={type:'variable',variable:definition.id,valueType:definition.type,array:definition.container==='array'},value=binding.variables.has(definition.id)?binding.variables.get(definition.id):definition.value;if(!validSequenceValue(track,value))throw Error('녹화 BP 변수의 자료형을 확인하세요: '+definition.name);rows.push({...track,key:'variable|'+definition.id,name:definition.name,value,discrete:sequenceValueDiscrete(track)});}for(const definition of binding.root.native?.classes.find(c=>c.name===object.nativeClass)?.properties||[]){if(definition.readOnly||seen.has('n:'+definition.name))continue;seen.add('n:'+definition.name);const track={type:'nativeProperty',className:object.nativeClass,property:definition.name,valueType:definition.type,array:definition.array},value=Object.hasOwn(object.nativeProperties||{},definition.name)?object.nativeProperties[definition.name]:definition.value??(definition.array?[]:defaultsFor(definition.type));if(!validSequenceValue(track,value))throw Error('녹화 C++ 속성의 자료형을 확인하세요: '+definition.name);rows.push({...track,key:'native|'+object.nativeClass+'.'+definition.name,name:definition.name,value,discrete:sequenceValueDiscrete(track)});}}return rows;}
export function readSequenceValue(object,track,bindings){return structuredClone(descriptor(object,track,bindings).value);}
export function prepareSequenceValues(changes,bindings,vm){return changes.map(({object,track,value})=>{if(!validSequenceValue(track,value))throw Error('시퀀스 변수 키 자료형 오류');const target=descriptor(object,track,bindings),reference=id=>{if(id===null)return null;const actor=vm.object(id==='self'?object.id:id);if(!actor)return null;if(target.definition.className&&!(actor.actorClasses||actorClassNames(actor)).includes(target.definition.className))throw Error('시퀀스 오브젝트 참조 클래스 오류');return actor.id;},scalar=v=>track.valueType==='object'?reference(v):track.valueType==='hit'?{...structuredClone(v),actor:reference(v.actor)}:structuredClone(v);return {target,track,value:track.array?value.map(scalar):scalar(value)};});}
export function applySequenceValues(prepared){for(const {target,track,value}of prepared)if(track.type==='variable')target.binding.variables.set(track.variable,value);else{target.object.nativeProperties??={};Object.defineProperty(target.object.nativeProperties,track.property,{value,writable:true,configurable:true,enumerable:true});}}
